INSERT INTO `areatable_dbc` (`ID`, `ContinentID`, `ParentAreaID`, `AreaBit`, `Flags`, `SoundProviderPref`, `SoundProviderPrefUnderwater`, `AmbienceID`, `ZoneMusic`, `IntroSound`, `ExplorationLevel`, `AreaName_Lang_enUS`, `AreaName_Lang_enGB`, `AreaName_Lang_koKR`, `AreaName_Lang_frFR`, `AreaName_Lang_deDE`, `AreaName_Lang_enCN`, `AreaName_Lang_zhCN`, `AreaName_Lang_enTW`, `AreaName_Lang_zhTW`, `AreaName_Lang_esES`, `AreaName_Lang_esMX`, `AreaName_Lang_ruRU`, `AreaName_Lang_ptPT`, `AreaName_Lang_ptBR`, `AreaName_Lang_itIT`, `AreaName_Lang_Unk`, `AreaName_Lang_Mask`, `FactionGroupMask`, `LiquidTypeID_1`, `LiquidTypeID_2`, `LiquidTypeID_3`, `LiquidTypeID_4`, `MinElevation`, `Ambient_Multiplier`, `Lightid`) VALUES
(5093, 0, 46, 3822, 1073741888, 0, 0, 0, 524, 0, 52, 'Karfang Hold', 'Karfang Hold', 'Karfang Hold', 'Karfang Hold', 'Karfang Hold', 'Karfang Hold', 'Karfang Hold', 'Karfang Hold', 'Karfang Hold', 'Karfang Hold', 'Karfang Hold', 'Karfang Hold', 'Karfang Hold', 'Karfang Hold', 'Karfang Hold', 'Karfang Hold', 16712190, 0, 0, 0, 0, 0, -500.0, 0.0, 0),
(5101, 0, 46, 3823, 1073741888, 0, 0, 46, 10, 0, 47, 'Hateforge Excavation', 'Hateforge Excavation', 'Hateforge Excavation', 'Hateforge Excavation', 'Hateforge Excavation', 'Hateforge Excavation', 'Hateforge Excavation', 'Hateforge Excavation', 'Hateforge Excavation', 'Hateforge Excavation', 'Hateforge Excavation', 'Hateforge Excavation', 'Hateforge Excavation', 'Hateforge Excavation', 'Hateforge Excavation', 'Hateforge Excavation', 16712190, 0, 0, 0, 0, 0, -500.0, 0.0, 0);
INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(60833, 0, 0, 'I was once the High Foreman of the Shadowforge Miners Union. Me and my men helped build many of the halls of the city itself, and worked tirelessly to appease the Senators of their plots and whims. We kept our loyalty, and then worked hard, given benefits for our work.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66429'),
(60833, 1, 0, 'It was then the plans of the Senate failed and the Master became upset that their wrath upon us started growing. The project at Hateforge Quarry put many to their limit, and pulled us away from our home to work in dangerous conditions without any regards for what we did in the past.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66430'),
(60833, 2, 0, 'We were given impossible tasks, which we could not complete, and I was placed to blame. Many of my fellow miners betrayed me, and a new High Foreman was put into my place. Those that remained loyal were enslaved, and the rest of us were exiled. We ended up travelling in exile for days, many of us dying.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66431'),
(60833, 3, 0, 'I was betrayed, backstabbed, and wronged. My heart burns hotter than the Blackrock Mountain, and I demand revenge. Do you see why I ask for help? No doubt you have your reasons to stop the Dark Iron. Let me guide your hand, and we shall both be satisfied.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66432'),
(60833, 4, 0, 'Been an honor working with you.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66433'),
(60763, 0, 0, 'The power within these hearts shall aid me, but it is weak, and faded, if I am to truly master my magic, than I need something much stronger.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66444'),
(60763, 1, 0, 'The power flows through my veins! I feel stronger, and mighty! With this, we shall dominate our enemies!', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66445'),
(60770, 0, 0, 'In the name of Raz\'gol, a warrior of the Horde, a soldier until his last breath. Go with honor friend, you will not be forgotten.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66446'),
(60770, 1, 0, 'Without you, we surely would have had our plans discovered, for that I am grateful of your service.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66447'),
(60770, 2, 0, 'Your name shall echo with honor for the actions you have taken, walk softly, noble soldier of the Horde.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66448');
